{
    "wsIdentificationValidationNegResponse": {
        "wsResponseHeader": {
			"system": {
	        	"name": vars.attributes.name,
	        	"correlationId":vars.attributes.correlationId,
	        	"processingServer": vars.attributes.source
         },
            "service": {
         	"status": p('etbpymeDataServices.response.service.passCode'),
