                "statusDetail": {
                    "errorCode": payload.code default null,
                    "errorDetailCode": payload.message default null,
                    "errorMessage": payload.messageServer default null
                }
            },
            "property": null
        }, identificationValidationResponse: payload.identificationValidationResponse
 }
}
